//! Golden-vector freeze tests for the temprun arena.
//!
//! Convention (same as the repo determinism courts): these fixtures are
//! FROZEN receipts generated by running the real arena at freeze time. The
//! tests below regenerate each vector live and compare BYTE-EXACT against
//! `tests/fixtures/*.golden`. Any future arena change that shifts a receipt
//! or digest breaks loudly — that is the point. Regenerating the fixtures is
//! a DELIBERATE DIFF: run
//! `cargo test -p temprun --test golden_vectors_test -- --ignored regenerate_golden --nocapture`
//! and review the emitted vectors as you would any breaking receipt change,
//! updating every affected `.golden` in the same commit as the arena change
//! that caused it.
//!
//! Vector set (10 positive + 1 negative):
//!   01 minimal            — empty tables, single-node clock advance, root commit
//!   02 max-fuel           — diverse valid input, fuel u64::MAX
//!   03 fuel-3 boundary    — exact-exhaustion admit (3 units charged)
//!   04 fuel-2 refusal     — one unit short; conformance charge fails
//!   05 empty payload      — empty commit message, empty tree
//!   06 4 MiB payload      — LCG-generated commit message, multi-entry tree
//!   07 clock extremes     — clock/observed at u64::MAX boundary
//!   08 coord collision    — candidate/lease mask intersection (refusal)
//!   09 full tree + parent — 256 deterministic entries, nonzero parent
//!   10 malformed negative — clock/observed arity mismatch -> typed refusal,
//!                           exact refusal bytes frozen (negative golden)

use std::fs;

use temprun::fuel::FuelLease;
use temprun::{run, ArenaInput, ParentLedger, RECEIPT_LEN};

const FIXTURE_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures");

/// Bump on any golden text layout change. `load_golden` REFUSES files whose
/// `format:` line is missing or unrecognized — a stale/foreign layout can
/// never silently re-parse into garbage (the N04 v1-writer class).
const GOLDEN_FORMAT: u32 = 1;

/// MMIX LCG (Knuth) — same deterministic generator family as arena_fuzz_test.
struct Lcg(u64);

impl Lcg {
    fn next_u64(&mut self) -> u64 {
        self.0 = self
            .0
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        self.0
    }
}

fn filled(seed: u64, len: usize) -> Vec<u8> {
    let mut g = Lcg(seed);
    (0..len).map(|_| g.next_u64() as u8).collect()
}

fn hashes(seed: u64, n: usize) -> Vec<([u8; 32], [u8; 32])> {
    let mut g = Lcg(seed);
    (0..n)
        .map(|_| {
            let mut p = [0u8; 32];
            let mut c = [0u8; 32];
            for b in p.iter_mut() {
                *b = g.next_u64() as u8;
            }
            for b in c.iter_mut() {
                *b = g.next_u64() as u8;
            }
            (p, c)
        })
        .collect()
}

fn parent_from(seed: u64) -> [u8; 32] {
    let mut p = [0u8; 32];
    for (i, b) in filled(seed, 32).into_iter().enumerate() {
        p[i] = b;
    }
    p
}

/// Each profile rebuilds a FRESH ArenaInput (`run` zeroizes its argument).
fn profile(id: &str) -> (ArenaInput, u64) {
    match id {
        "01_minimal" => (
            ArenaInput {
                lineage: vec![],
                policy: vec![],
                clock: vec![1],
                observed: vec![0],
                candidate_mask: 0,
                lease_mask: 0,
                tree_entries: vec![],
                parent: [0u8; 32],
                message: b"x".to_vec(),
            },
            10,
        ),
        "02_max_fuel" => (
            ArenaInput {
                lineage: vec![[1, 2, 3, 10], [4, 5, 6, 20], [7, 8, 9, 30]],
                policy: vec![[1, 2, 3, 0], [4, 5, 6, 0], [7, 8, 9, 0]],
                clock: vec![5, 3, 1],
                observed: vec![5, 2, 0],
                candidate_mask: 0b0100,
                lease_mask: 0b0010,
                tree_entries: hashes(7, 3),
                parent: parent_from(11),
                message: b"actuate v2".to_vec(),
            },
            u64::MAX,
        ),
        "03_fuel_3_boundary" => {
            let (mut inp, _) = profile("02_max_fuel");
            inp.message = b"boundary".to_vec();
            (inp, 3)
        }
        "04_fuel_2_refusal" => {
            let (mut inp, _) = profile("02_max_fuel");
            inp.message = b"boundary-short".to_vec();
            (inp, 2)
        }
        "05_empty_payload" => (
            ArenaInput {
                lineage: vec![[42, 43, 44, 7]],
                policy: vec![[42, 43, 44, 0]],
                clock: vec![9, 9],
                observed: vec![9, 8],
                candidate_mask: 1,
                lease_mask: 0,
                tree_entries: vec![],
                parent: [0u8; 32],
                message: vec![],
            },
            10,
        ),
        "06_payload_4mib" => (
            ArenaInput {
                lineage: vec![[100, 200, 300, 1]],
                policy: vec![[100, 200, 300, 0]],
                clock: vec![2],
                observed: vec![1],
                candidate_mask: 0,
                lease_mask: 0,
                tree_entries: hashes(13, 4),
                parent: [0u8; 32],
                message: filled(17, 4 * 1024 * 1024),
            },
            10,
        ),
        "07_clock_extremes" => (
            ArenaInput {
                lineage: vec![[1, 1, 1, u64::MAX]],
                policy: vec![[1, 1, 1, 0]],
                clock: vec![u64::MAX],
                observed: vec![u64::MAX - 1],
                candidate_mask: 0,
                lease_mask: u64::MAX,
                tree_entries: vec![([0u8; 32], [255u8; 32])],
                parent: [0u8; 32],
                message: b"extreme".to_vec(),
            },
            10,
        ),
        "08_coord_collision" => (
            ArenaInput {
                lineage: vec![[1, 2, 3, 1]],
                policy: vec![[1, 2, 3, 0]],
                clock: vec![1],
                observed: vec![0],
                candidate_mask: u64::MAX,
                lease_mask: 1,
                tree_entries: vec![],
                parent: [0u8; 32],
                message: b"collision".to_vec(),
            },
            10,
        ),
        "09_full_tree_parent" => (
            ArenaInput {
                lineage: vec![[9, 9, 9, 4]],
                policy: vec![[9, 9, 9, 0]],
                clock: vec![4, 4, 4],
                observed: vec![3, 3, 3],
                candidate_mask: 0,
                lease_mask: 0,
                tree_entries: hashes(19, 256),
                parent: parent_from(23),
                message: filled(29, 512),
            },
            10,
        ),
        // Negative golden: fixed malformed input (clock/observed arity
        // mismatch trips the clock sieve) -> frozen typed refusal bytes.
        "10_malformed_refusal" => (
            ArenaInput {
                lineage: vec![],
                policy: vec![],
                clock: vec![1, 2],
                observed: vec![1],
                candidate_mask: 0,
                lease_mask: 0,
                tree_entries: vec![],
                parent: [0u8; 32],
                message: b"malformed".to_vec(),
            },
            10,
        ),
        other => panic!("unknown profile {other}"),
    }
}

const PROFILES: [&str; 10] = [
    "01_minimal",
    "02_max_fuel",
    "03_fuel_3_boundary",
    "04_fuel_2_refusal",
    "05_empty_payload",
    "06_payload_4mib",
    "07_clock_extremes",
    "08_coord_collision",
    "09_full_tree_parent",
    "10_malformed_refusal",
];

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn parse_hex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16))
        .collect::<Result<Vec<u8>, _>>()
        .unwrap()
}

fn emit_golden() {
    fs::create_dir_all(FIXTURE_DIR).unwrap();
    for id in PROFILES {
        let (mut inp, fuel) = profile(id);
        let out = run(&mut inp, FuelLease::new(fuel), &mut ParentLedger::new());
        let text = format!(
            "// frozen golden vector: profile {id}, fuel {fuel}\n// regenerate = deliberate diff (see test header)\nformat: {GOLDEN_FORMAT}\nadmitted: {}\nreceipt: {}\nuniverse_digest: {}\n",
            out.admitted,
            hex(&out.receipt),
            hex(&out.universe_digest),
        );
        fs::write(format!("{FIXTURE_DIR}/{id}.golden"), text).unwrap();
        println!("wrote {id}");
    }
}

#[test]
#[ignore = "fixture generator: deliberate diff only"]
fn regenerate_golden() {
    emit_golden();
}

fn load_golden(id: &str) -> (bool, [u8; RECEIPT_LEN], [u8; 32]) {
    let text = fs::read_to_string(format!("{FIXTURE_DIR}/{id}.golden"))
        .unwrap_or_else(|e| panic!("missing fixture {id}.golden: {e}"));
    let mut format = None;
    let mut admitted = None;
    let mut receipt = None;
    let mut digest = None;
    for line in text.lines() {
        if let Some(v) = line.strip_prefix("format: ") {
            format = Some(v.parse::<u32>().unwrap());
        }
        if let Some(v) = line.strip_prefix("admitted: ") {
            admitted = Some(v.parse::<bool>().unwrap());
        } else if let Some(v) = line.strip_prefix("receipt: ") {
            let b = parse_hex(v);
            receipt = Some(b.try_into().unwrap());
        } else if let Some(v) = line.strip_prefix("universe_digest: ") {
            let b = parse_hex(v);
            digest = Some(b.try_into().unwrap());
        }
    }
    assert_eq!(
        format,
        Some(GOLDEN_FORMAT),
        "{id}: golden format marker missing or foreign — regenerate, never silently re-parse"
    );
    (
        admitted.expect("admitted line"),
        receipt.expect("receipt line"),
        digest.expect("digest line"),
    )
}

#[test]
fn golden_vectors_reproduce_byte_exact() {
    for id in PROFILES {
        let (want_admitted, want_receipt, want_digest) = load_golden(id);
        let (mut inp, fuel) = profile(id);
        let out = run(&mut inp, FuelLease::new(fuel), &mut ParentLedger::new());
        assert_eq!(out.admitted, want_admitted, "{id}: admitted flag drifted");
        assert_eq!(
            out.receipt, want_receipt,
            "{id}: receipt bytes drifted from frozen golden"
        );
        assert_eq!(
            out.universe_digest, want_digest,
            "{id}: universe digest drifted from frozen golden"
        );
        // Shape invariant: every receipt, admit or refusal, is exactly 32B.
        assert_eq!(out.receipt.len(), RECEIPT_LEN);
    }
}

#[test]
fn negative_golden_refusal_is_constant_shape() {
    // The malformed negative golden must refuse with the exact frozen bytes
    // AND retain the constant-time shape contract (32B, no error entropy).
    let (want_admitted, want_receipt, want_digest) = load_golden("10_malformed_refusal");
    assert!(!want_admitted, "negative golden must be a refusal");
    let (mut inp, fuel) = profile("10_malformed_refusal");
    let out = run(&mut inp, FuelLease::new(fuel), &mut ParentLedger::new());
    assert!(!out.admitted);
    assert_eq!(out.receipt, want_receipt);
    assert_eq!(out.universe_digest, want_digest);
    // Refusal shares bytes 1..31 with its admit twin and pins byte 0 to the
    // 0x02 status code — no error-class entropy leaked into the receipt.
    let (mut clean, fuel) = profile("10_malformed_refusal");
    clean.clock = vec![1, 2];
    clean.observed = vec![1, 1];
    let twin = run(&mut clean, FuelLease::new(fuel), &mut ParentLedger::new());
    assert!(twin.admitted);
    assert_eq!(out.receipt[1..], twin.receipt[1..]);
    assert_eq!(out.receipt[0], temprun::receipt::REFUSED_STATUS);
}

// Fixture-inventory court: the fixtures directory must contain EXACTLY the
// PROFILES set — no orphaned `.golden` that no test reads, no missing file.
// Every file must also carry the current format marker and its own profile
// header, so a stray or stale fixture fails loudly instead of sitting.
#[test]
fn golden_fixture_inventory_exact() {
    let mut expected: Vec<String> = PROFILES.iter().map(|id| format!("{id}.golden")).collect();
    expected.sort();
    let mut on_disk: Vec<String> = fs::read_dir(FIXTURE_DIR)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    on_disk.sort();
    assert_eq!(
        on_disk, expected,
        "fixtures dir != PROFILES set (orphan or missing golden)"
    );
    for id in PROFILES {
        let text = fs::read_to_string(format!("{FIXTURE_DIR}/{id}.golden")).unwrap();
        let header = format!(
            "// frozen golden vector: profile {id}, fuel {}",
            profile(id).1
        );
        assert_eq!(
            text.lines().next(),
            Some(header.as_str()),
            "{id}: stale or foreign golden header"
        );
        assert!(
            text.lines()
                .any(|l| l == format!("format: {GOLDEN_FORMAT}")),
            "{id}: missing format marker — regenerate the golden"
        );
    }
}
